    26  void TwineChar16::print(llvh::raw_ostream &os) const {
    27    assert(isValid());
    28    auto printChild = [&os](const Node child, const NodeKind kind, size_t size) {
    29      switch (kind) {
    30        case TwineChar16::NullKind:
    31        case TwineChar16::EmptyKind:
    32          break;
    33        case TwineChar16::TwineKind:
    34          child.twine->print(os);
    35          break;
    36        case TwineChar16::CharStrKind:
    37          os << llvh::StringRef(child.charStr, size);
    38          break;
    39        case TwineChar16::Char16StrKind:
    40          os << UTF16Ref(child.char16Str, size);
    41          break;
    42        case TwineChar16::StringPrimitiveKind: {
    43          SmallU16String<32> str;
    44          child.stringPrimitive->appendUTF16String(str);
    45          os << str;
    46          break;
    47        }
    48        case TwineChar16::Int32Kind:
    49          os << child.int32;
    50          break;
    51        case TwineChar16::Unsigned32Kind:
    52          os << child.uint32;
    53          break;
    54        case TwineChar16::DoubleKind:
    55          char buf[NUMBER_TO_STRING_BUF_SIZE];
    56          auto len = numberToString(child.flt, buf, sizeof(buf));
    57          assert(len < sizeof(buf));
    58          buf[len] = '\0';
    59          os << buf;
    60          break;
    61      }
    62    };
    63    printChild(leftChild_, leftKind_, leftSize_);
    64    printChild(rightChild_, rightKind_, rightSize_);
    65  }
